style.css:
@-moz-document domain("images.example.com"), url-prefix("https://jenkins.omnimed.com/blue/organizations/jenkins/") {
/* COLORS
Sucess: #3C581C
Failure: #6B262A
Default: #254871
Dark bg: #2B2B2B
Light bg: #555555
Text: #D5D5D5
*/


/* Headers */
.BasicHeader--default {
    background: #254871;
}

.BasicHeader--success {
    background: #3C581C;
}

.BasicHeader--failure {
    background: #6B262A;
}

.BasicHeader--running {
    background: #274B75;
}

.BasicHeader--paused {
    background: #18758E;
}

/* Main content */
.FullScreen-contents {
    background: #2B2B2B;
    color: #D5D5D5;
}

circle.halo {
  stroke: #949393;
}

 /* Logs */
.logConsole {
    background-color: #555555;
}

.result-item-head {
    background-color: #555555;
    border: solid 1px #555555;
    color: #D5D5D5;
}

.result-item-title {
      background-color: #555555;
}

.result-bg.success {
    background: #3C581C;
    border-bottom: solid 1px #3C581C;
}

.result-bg.failure {
  background: #6B262A;
  border-bottom: solid 1px #6B262A;
}result-bg.failure {
  background: #6B262A;
  border-bottom: solid 1px #6B262A;
}
}
